// Stage 3 — Input Validation + Stage 4 — Business Logic.
// Select recently-finished events worth ingesting. A short lookback keeps the
// run cheap; idempotent path writes make overlap harmless.
const LOOKBACK_DAYS = 7;

const destPayload = $('Fetch Destinations').first().json;
const destinations = (destPayload.items || destPayload || [])
  .filter(c => c && (c.streamingPlatformId || c.platformId || c.platform))
  .map(c => ({
    platform: c.platform || c.streamingPlatformId || c.platformId || null,
    display_name: c.displayName || c.name || null,
    enabled: c.enabled !== false
  }));

const body = $input.first().json;
const events = body.items || body || [];
if (!Array.isArray(events)) {
  throw new Error('events-history did not return a list. Check API base URL and OAuth scopes.');
}

const cutoff = Date.now() - LOOKBACK_DAYS * 86400000;
const toIso = (v) => {
  if (v === undefined || v === null) return null;
  const d = typeof v === 'number' ? new Date(v * (v < 1e12 ? 1000 : 1)) : new Date(v);
  return isNaN(d.getTime()) ? null : d.toISOString().replace(/\.\d{3}Z$/, 'Z');
};

const selected = [];
for (const e of events) {
  const id = e.id || e.eventIdentifier || null;
  if (!id) continue;
  const started = toIso(e.scheduledFor ?? e.startedAt ?? e.createdAt);
  if (started && new Date(started).getTime() < cutoff) continue;
  selected.push({ json: {
    event_id: id,
    title: e.title || e.name || null,
    started_at: started,
    destinations
  }});
}

if (!selected.length) {
  // Not an error. No council streams in the window is a normal quiet week.
  return [{ json: { _noop: true, reason: `no events in last ${LOOKBACK_DAYS} days`, destinations } }];
}
return selected;

// Stages 5 & 6 — Normalization and Result Validation.
const meta = $('Select Recent Events').item.json;
const chatRaw = $('Fetch Chat History').item.json;
const viewRaw = $input.first().json;

const num = (v) => (v === undefined || v === null ? null : Number(v));
const toIso = (v) => {
  if (v === undefined || v === null) return null;
  const d = typeof v === 'number' ? new Date(v * (v < 1e12 ? 1000 : 1)) : new Date(v);
  return isNaN(d.getTime()) ? null : d.toISOString().replace(/\.\d{3}Z$/, 'Z');
};

const rawMsgs = chatRaw.items || chatRaw.messages || chatRaw || [];
if (!Array.isArray(rawMsgs)) throw new Error('Chat history did not return a list.');

const messages = rawMsgs.map((m, i) => {
  const text = m.text || m.message || m.content || null;
  return {
    id: m.id || `${meta.event_id}:${i}`,
    platform: m.platform || m.streamingPlatformId || null,
    author: m.author || m.username || m.displayName || null,
    text,
    posted_at: toIso(m.timestamp ?? m.createdAt ?? m.sentAt),
    // Question detection is deliberately conservative here; canonicalisation
    // and recurrence counting happen downstream against questions[].
    is_question: !!(text && /\?/.test(text)),
    tier: 'measured'
  };
}).filter(m => m.text);

// Reconciliation: every message either normalized or explicitly dropped.
const dropped = rawMsgs.length - messages.length;
if (dropped < 0) throw new Error('Reconciliation failed: more messages out than in.');

const viewers = {
  peak_viewers: num(viewRaw.peakViewers ?? viewRaw.peak ?? null),
  total_views: num(viewRaw.totalViews ?? viewRaw.views ?? null),
  by_platform: viewRaw.byPlatform || viewRaw.platforms || null,
  tier: 'measured'
};

const now = new Date().toISOString().replace(/\.\d{3}Z$/, 'Z');
const date = (meta.started_at || now).slice(0, 10);
const slug = String(meta.title || meta.event_id)
  .toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 48) || 'event';

const doc = {
  schema_version: 2,
  date,
  scraped_at: now,
  data_status: 'measured',
  collection: {
    method: 'restream_api_v2',
    workflow: 'PROD-RESTREAM-CouncilStream-Pull-v1.0',
    event_id: meta.event_id,
    coverage: 'census',
    messages_returned: rawMsgs.length,
    messages_normalized: messages.length,
    messages_dropped_no_text: dropped,
    notes: 'Chat aggregated across all stream destinations. Viewer figures are point-in-time for this live event and are NOT comparable to YouTube lifetime view counts.'
  },
  event: {
    event_id: meta.event_id,
    title: meta.title,
    started_at: meta.started_at,
    layer: 'governance',
    narratives: []
  },
  destinations: meta.destinations,
  viewers,
  messages,
  question_count: messages.filter(m => m.is_question).length,
  _ingested_at: now,
  _source_system: 'restream_api_v2'
};

return [{ json: { doc, path: `campaign/analytics/streams/${date}-${slug}.json`,
  summary: `${messages.length} chat messages, ${doc.question_count} questions` } }];

// Stages 8 & 9 — Error Branch and Manual Recovery. Writes NOTHING.
const e = $input.first().json;
const msg = e.error?.message || e.message || JSON.stringify(e).slice(0, 400);
let cause = 'unknown';
if (/401|unauthor/i.test(msg)) cause = 'AUTH - Restream OAuth token expired or scope missing; reauthorize in n8n';
else if (/403/.test(msg)) cause = 'FORBIDDEN - API access may be gated behind a paid Restream tier';
else if (/429/.test(msg)) cause = 'RATE_LIMITED';
else if (/404/.test(msg)) cause = 'NOT_FOUND - check API base URL is https://api.restream.io/v2';
else if (/Reconciliation/i.test(msg)) cause = 'RECONCILIATION_FAILED';
else if (/timeout|ETIMEDOUT|ENOTFOUND/i.test(msg)) cause = 'NETWORK';
return [{ json: {
  workflow: 'PROD-RESTREAM-CouncilStream-Pull-v1.0',
  executed_at: new Date().toISOString(),
  source_system: 'restream_api_v2',
  status: 'FAILED',
  error_class: cause,
  cause_note: msg,
  wrote_data: false,
  manual_recovery: 'Reauthorize the Restream OAuth2 credential in n8n, then re-run. Chat history retention is unconfirmed - if a council stream ages out before ingest, that data is unrecoverable.'
}}];
